import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';

function fib(n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }

if (isMainThread) {
  const run = (n) => new Promise((resolve, reject) => {
    const w = new Worker(new URL(import.meta.url), { workerData: n });
    w.on('message', resolve);
    w.on('error', reject);
  });

  console.time('parallel');
  const results = await Promise.all([run(38), run(38), run(38)]);
  console.timeEnd('parallel');
  console.log(results);                 // [ 39088169, 39088169, 39088169 ]
} else {
  parentPort.postMessage(fib(workerData));
}

import cluster from 'node:cluster';
import http from 'node:http';
import os from 'node:os';

if (cluster.isPrimary) {
  const n = os.availableParallelism();
  console.log(`primary ${process.pid} starting ${n} workers`);
  for (let i = 0; i < n; i++) cluster.fork();

  cluster.on('exit', (worker, code) => {
    console.log(`worker ${worker.process.pid} died (${code}), restarting`);
    cluster.fork();
  });
} else {
  http.createServer((req, res) => {
    res.end(`handled by ${process.pid}\n`);
  }).listen(3000);
}

